import React, { useState } from 'react';
import { format } from 'date-fns';
import './LogTable.css';
import './ImageLogTable.css';

const ImageLogTable = ({ 
  logs, 
  loading, 
  sortField, 
  sortDirection, 
  onSort, 
  currentPage, 
  totalPages, 
  onPageChange,
  keywords = []
}) => {
  // 정렬 아이콘 렌더링
  const renderSortIcon = (field) => {
    if (sortField !== field) {
      return <span className="sort-icon">↕</span>;
    }
    return sortDirection === 'asc' ? 
      <span className="sort-icon">↑</span> : 
      <span className="sort-icon">↓</span>;
  };

  // 시간 포맷팅
  const formatTime = (timeString) => {
    if (!timeString) return '';
    
    // datetime-local 형식 처리 (YYYY-MM-DDTHH:mm:ss)
    if (typeof timeString === 'string' && timeString.includes('T')) {
      try {
        const date = new Date(timeString);
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');
        const seconds = String(date.getSeconds()).padStart(2, '0');
        return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
      } catch (error) {
        return timeString;
      }
    }
    
    // yyyy-MM-dd HH:mm:ss 형식
    if (typeof timeString === 'string' && timeString.match(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/)) {
      return timeString;
    }
    
    return timeString;
  };

  // JSON 문자열을 pretty print로 변환
  const formatJsonString = (text, pretty = false) => {
    if (!text) return '';
    
    try {
      const parsed = JSON.parse(text);
      return pretty ? JSON.stringify(parsed, null, 2) : JSON.stringify(parsed);
    } catch (e) {
      return text; // JSON이 아니면 원본 반환
    }
  };
  
  // 키워드 하이라이트
  const highlightKeywords = (text, keywords) => {
    if (!text || !keywords || keywords.length === 0) {
      return text;
    }
    
    let highlightedText = String(text);
    keywords.forEach(keyword => {
      if (keyword) {
        const regex = new RegExp(`(${keyword})`, 'gi');
        highlightedText = highlightedText.replace(regex, '<mark>$1</mark>');
      }
    });
    
    return <span dangerouslySetInnerHTML={{ __html: highlightedText }} />;
  };
  
  // 상세 보기 상태
  const [selectedLog, setSelectedLog] = useState(null);
  const [prettyPrint, setPrettyPrint] = useState(true);
  
  // Pretty 출력 상태 (각 로그별로 관리)
  const [prettyLogs, setPrettyLogs] = useState(new Set());
  
  // 상세 보기 열기
  const handleViewDetail = (log) => {
    setSelectedLog(log);
  };
  
  // 상세 보기 닫기
  const handleCloseDetail = () => {
    setSelectedLog(null);
  };
  
  // Pretty 출력 토글
  const togglePretty = (guid) => {
    setPrettyLogs(prev => {
      const newSet = new Set(prev);
      if (newSet.has(guid)) {
        newSet.delete(guid);
      } else {
        newSet.add(guid);
      }
      return newSet;
    });
  };
  
  // Pretty 출력 여부 확인
  const isPretty = (guid) => {
    return prettyLogs.has(guid);
  };

  // 페이지 번호 생성
  const getPageNumbers = () => {
    const pages = [];
    const maxPages = 10;
    let startPage = Math.max(1, currentPage - Math.floor(maxPages / 2));
    let endPage = Math.min(totalPages, startPage + maxPages - 1);
    
    if (endPage - startPage < maxPages - 1) {
      startPage = Math.max(1, endPage - maxPages + 1);
    }
    
    for (let i = startPage; i <= endPage; i++) {
      pages.push(i);
    }
    
    return pages;
  };

  if (loading) {
    return (
      <div className="log-table-container">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>데이터를 불러오는 중...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="log-table-container">
      <div className="table-wrapper">
        <table className="log-table">
          <thead>
            <tr>
              <th 
                onClick={() => onSort('insert_time')}
                className="sortable-header"
              >
                insert_time {renderSortIcon('insert_time')}
              </th>
              <th 
                onClick={() => onSort('application')}
                className="sortable-header"
              >
                application {renderSortIcon('application')}
              </th>
              <th 
                onClick={() => onSort('servicegroup')}
                className="sortable-header"
              >
                servicegroup {renderSortIcon('servicegroup')}
              </th>
              <th 
                onClick={() => onSort('service')}
                className="sortable-header"
              >
                service {renderSortIcon('service')}
              </th>
              <th 
                onClick={() => onSort('status')}
                className="sortable-header"
              >
                status {renderSortIcon('status')}
              </th>
              <th>guid</th>
              <th>datastring</th>
              <th>headerstring</th>
              <th>Pretty</th>
            </tr>
          </thead>
          <tbody>
            {logs.length === 0 ? (
              <tr>
                <td colSpan="9" className="no-data">
                  검색 결과가 없습니다.
                </td>
              </tr>
            ) : (
              logs.map((log, index) => {
                const logGuid = log.guid || `log-${index}`;
                const isPrettyMode = isPretty(logGuid);
                const datastringValue = log.datastring || log.decrypted_data || log.data || '';
                const headerstringValue = log.headerstring || log.decrypted_header || log.header || '';
                
                return (
                  <tr key={`imagelog-${index}-${logGuid}`}>
                    <td>{formatTime(log.insert_time || log.timestamp)}</td>
                    <td>{log.application || ''}</td>
                    <td>{log.servicegroup || ''}</td>
                    <td>{log.service || ''}</td>
                    <td>{log.status || ''}</td>
                    <td>{logGuid}</td>
                    <td className={`tr-data-cell ${isPrettyMode ? 'pretty-mode' : ''}`}>
                      {isPrettyMode ? (
                        <pre className="json-pretty-text">
                          {formatJsonString(datastringValue, true)}
                        </pre>
                      ) : (
                        <span className="tr-data-text">
                          {highlightKeywords(datastringValue, keywords)}
                        </span>
                      )}
                    </td>
                    <td className={`tr-data-cell ${isPrettyMode ? 'pretty-mode' : ''}`}>
                      {isPrettyMode ? (
                        <pre className="json-pretty-text">
                          {formatJsonString(headerstringValue, true)}
                        </pre>
                      ) : (
                        <span className="tr-data-text">
                          {highlightKeywords(headerstringValue, keywords)}
                        </span>
                      )}
                    </td>
                    <td className="pretty-action-cell">
                      <button
                        className={`pretty-btn ${isPrettyMode ? 'active' : ''}`}
                        onClick={() => togglePretty(logGuid)}
                        title={isPrettyMode ? 'Pretty 출력 끄기' : 'Pretty 출력 켜기'}
                      >
                        {isPrettyMode ? 'Pretty OFF' : 'Pretty'}
                      </button>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
      
      {totalPages > 1 && (
        <div className="pagination">
          <button 
            onClick={() => onPageChange(1)}
            disabled={currentPage === 1}
            className="page-button"
          >
            처음
          </button>
          <button 
            onClick={() => onPageChange(currentPage - 1)}
            disabled={currentPage === 1}
            className="page-button"
          >
            이전
          </button>
          
          {getPageNumbers().map(page => (
            <button
              key={page}
              onClick={() => onPageChange(page)}
              className={`page-button ${currentPage === page ? 'active' : ''}`}
            >
              {page}
            </button>
          ))}
          
          <button 
            onClick={() => onPageChange(currentPage + 1)}
            disabled={currentPage === totalPages}
            className="page-button"
          >
            다음
          </button>
          <button 
            onClick={() => onPageChange(totalPages)}
            disabled={currentPage === totalPages}
            className="page-button"
          >
            마지막
          </button>
        </div>
      )}
      
      {/* 상세 보기 모달 */}
      {selectedLog && (
        <div className="detail-modal-overlay" onClick={handleCloseDetail}>
          <div className="detail-modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="detail-modal-header">
              <h2>로그 상세 정보</h2>
              <button className="close-btn" onClick={handleCloseDetail}>×</button>
            </div>
            <div className="detail-modal-body">
              <div className="detail-section">
                <h3>기본 정보</h3>
                <table className="detail-table">
                  <tbody>
                    <tr><td>GUID</td><td>{selectedLog.guid || ''}</td></tr>
                    <tr><td>Application</td><td>{selectedLog.application || ''}</td></tr>
                    <tr><td>Service Group</td><td>{selectedLog.servicegroup || ''}</td></tr>
                    <tr><td>Service</td><td>{selectedLog.service || ''}</td></tr>
                    <tr><td>Status</td><td>{selectedLog.status || ''}</td></tr>
                    <tr><td>Insert Time</td><td>{formatTime(selectedLog.insert_time || selectedLog.timestamp)}</td></tr>
                  </tbody>
                </table>
              </div>
              
              <div className="detail-section">
                <div className="detail-section-header">
                  <h3>Data String</h3>
                  <label className="pretty-print-toggle">
                    <input 
                      type="checkbox" 
                      checked={prettyPrint}
                      onChange={(e) => setPrettyPrint(e.target.checked)}
                    />
                    Pretty Print
                  </label>
                </div>
                <pre className="json-content">
                  {formatJsonString(selectedLog.datastring || selectedLog.decrypted_data || selectedLog.data || '', prettyPrint)}
                </pre>
              </div>
              
              <div className="detail-section">
                <div className="detail-section-header">
                  <h3>Header String</h3>
                  <label className="pretty-print-toggle">
                    <input 
                      type="checkbox" 
                      checked={prettyPrint}
                      onChange={(e) => setPrettyPrint(e.target.checked)}
                    />
                    Pretty Print
                  </label>
                </div>
                <pre className="json-content">
                  {formatJsonString(selectedLog.headerstring || selectedLog.decrypted_header || selectedLog.header || '', prettyPrint)}
                </pre>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ImageLogTable;

