import React, { useState, useEffect, useRef } from 'react';
import './AdvancedSearchForm.css';

const AdvancedSearchForm = ({ logType, onSearch }) => {
  const [tokens, setTokens] = useState([]);
  const [inputValue, setInputValue] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [suggestionIndex, setSuggestionIndex] = useState(-1);
  const [fieldMetadata, setFieldMetadata] = useState([]);
  const [currentContext, setCurrentContext] = useState('field'); // field | operator | value
  const [currentField, setCurrentField] = useState(null);
  const inputRef = useRef(null);
  const suggestionRef = useRef(null);

  // 필드 메타데이터 로드
  useEffect(() => {
    if (logType && logType.id === 'java_fw_imglog') {
      loadFieldMetadata();
    }
  }, [logType]);

  // 필드 메타데이터 로드
  const loadFieldMetadata = async () => {
    try {
      const apiBaseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:9200/api';
      const response = await fetch(`${apiBaseUrl}/log-types/java_fw_imglog/fields`);
      const result = await response.json();
      
      if (result.success) {
        setFieldMetadata(result.data || []);
      }
    } catch (error) {
      console.error('필드 메타데이터 로드 실패:', error);
    }
  };

  // 추천 조회
  const fetchSuggestions = async (context, prefix, fieldName) => {
    if (!logType || logType.id !== 'java_fw_imglog') return;
    
    try {
      const apiBaseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:9200/api';
      const url = `${apiBaseUrl}/search/suggest?logType=java_fw_imglog&context=${context}&prefix=${encodeURIComponent(prefix || '')}${fieldName ? `&fieldName=${encodeURIComponent(fieldName)}` : ''}`;
      const response = await fetch(url);
      const result = await response.json();
      
      if (result.success) {
        setSuggestions(result.data || []);
        setShowSuggestions(true);
        setSuggestionIndex(-1);
      }
    } catch (error) {
      console.error('추천 조회 실패:', error);
    }
  };

  // 입력값 변경 처리
  const handleInputChange = (e) => {
    const value = e.target.value;
    setInputValue(value);
    
    // 입력값 파싱하여 컨텍스트 결정
    const context = parseContext(value);
    setCurrentContext(context.context);
    setCurrentField(context.field);
    
    // 추천 조회 (디바운스)
    if (value.trim()) {
      clearTimeout(window.suggestionTimeout);
      window.suggestionTimeout = setTimeout(() => {
        fetchSuggestions(context.context, context.prefix, context.field);
      }, 200);
    } else {
      setShowSuggestions(false);
      setSuggestions([]);
    }
  };

  // 입력값 파싱하여 컨텍스트 결정
  const parseContext = (input) => {
    const trimmed = input.trim();
    
    // 마지막 공백 이후의 텍스트
    const lastSpaceIndex = trimmed.lastIndexOf(' ');
    const currentPart = lastSpaceIndex >= 0 ? trimmed.substring(lastSpaceIndex + 1) : trimmed;
    
    // 필드명:값 형식인지 확인
    if (currentPart.includes(':')) {
      const [field, ...valueParts] = currentPart.split(':');
      if (valueParts.length > 0) {
        return {
          context: 'value',
          field: field,
          prefix: valueParts.join(':')
        };
      }
    }
    
    // 연산자 확인 (>=, <=, >, <, IN, NOT IN)
    if (currentPart.match(/^(>=|<=|>|<|IN|NOT IN)$/i)) {
      // 이전 토큰에서 필드명 찾기
      const lastToken = tokens[tokens.length - 1];
      if (lastToken && lastToken.type === 'field') {
        return {
          context: 'value',
          field: lastToken.value,
          prefix: ''
        };
      }
      return { context: 'operator', prefix: currentPart };
    }
    
    // 필드명 추천
    return { context: 'field', prefix: currentPart };
  };

  // 추천 선택
  const handleSuggestionSelect = (suggestion) => {
    const value = suggestion.value;
    const label = suggestion.label;
    
    if (currentContext === 'field') {
      // 필드명 선택 → 연산자 추천
      addToken({ type: 'field', value: value, label: label });
      setInputValue('');
      setCurrentContext('operator');
      setCurrentField(value);
      fetchSuggestions('operator', '', value);
    } else if (currentContext === 'operator') {
      // 연산자 선택 → 값 추천
      const lastToken = tokens[tokens.length - 1];
      if (lastToken && lastToken.type === 'field') {
        addToken({ type: 'operator', value: value, label: label, field: lastToken.value });
        setInputValue('');
        setCurrentContext('value');
        setCurrentField(lastToken.value);
        fetchSuggestions('value', '', lastToken.value);
      }
    } else if (currentContext === 'value') {
      // 값 선택 → 토큰 완성
      const lastFieldToken = tokens.filter(t => t.type === 'field').pop();
      const lastOperatorToken = tokens.filter(t => t.type === 'operator').pop();
      
      if (lastFieldToken && lastOperatorToken) {
        addToken({ type: 'value', value: value, label: label, field: lastFieldToken.value, operator: lastOperatorToken.value });
        setInputValue('');
        setShowSuggestions(false);
        setCurrentContext('field');
        setCurrentField(null);
      }
    }
  };

  // 토큰 추가
  const addToken = (token) => {
    const newToken = {
      id: Date.now().toString(),
      ...token,
      status: 'confirmed'
    };
    setTokens([...tokens, newToken]);
  };

  // 토큰 삭제
  const handleTokenDelete = (tokenId) => {
    setTokens(tokens.filter(t => t.id !== tokenId));
  };

  // 토큰 편집
  const handleTokenEdit = (tokenId) => {
    // 토큰을 입력창으로 이동하여 편집
    const token = tokens.find(t => t.id === tokenId);
    if (token) {
      if (token.type === 'field') {
        setInputValue(token.value);
        setCurrentContext('operator');
        setCurrentField(token.value);
      } else if (token.type === 'operator') {
        setInputValue(token.value);
        setCurrentContext('value');
      } else if (token.type === 'value') {
        setInputValue(token.value);
        setCurrentContext('value');
      }
      handleTokenDelete(tokenId);
      inputRef.current?.focus();
    }
  };

  // 키보드 이벤트 처리
  const handleKeyDown = (e) => {
    if (showSuggestions && suggestions.length > 0) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSuggestionIndex(prev => 
          prev < suggestions.length - 1 ? prev + 1 : prev
        );
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSuggestionIndex(prev => prev > 0 ? prev - 1 : -1);
      } else if (e.key === 'Enter') {
        e.preventDefault();
        if (suggestionIndex >= 0 && suggestionIndex < suggestions.length) {
          handleSuggestionSelect(suggestions[suggestionIndex]);
        } else if (suggestions.length > 0) {
          handleSuggestionSelect(suggestions[0]);
        } else {
          // 추천이 없으면 현재 입력값으로 토큰 생성 시도
          handleEnter();
        }
      } else if (e.key === 'Escape') {
        setShowSuggestions(false);
      }
    } else if (e.key === 'Enter') {
      handleEnter();
    } else if (e.key === 'Backspace' && inputValue === '' && tokens.length > 0) {
      // 입력창이 비어있을 때 백스페이스 → 마지막 토큰 삭제
      handleTokenDelete(tokens[tokens.length - 1].id);
    }
  };

  // 엔터 키 처리
  const handleEnter = () => {
    if (inputValue.trim()) {
      // 현재 컨텍스트에 따라 토큰 생성
      if (currentContext === 'field') {
        // 필드명으로 토큰 생성
        const field = fieldMetadata.find(f => 
          f.name.toLowerCase().startsWith(inputValue.toLowerCase()) ||
          f.label.toLowerCase().includes(inputValue.toLowerCase())
        );
        if (field) {
          addToken({ type: 'field', value: field.name, label: field.label });
          setInputValue('');
          setCurrentContext('operator');
          setCurrentField(field.name);
          fetchSuggestions('operator', '', field.name);
        }
      }
    }
  };

  // 검색 실행
  const handleSearch = () => {
    // 토큰을 AST로 변환
    const filters = buildFiltersFromTokens();
    
    const searchRequest = {
      logType: 'java_fw_imglog',
      queryText: inputValue.trim() || null,
      filters: filters,
      sort: [
        {
          field: 'insert_time',
          direction: 'desc'
        }
      ],
      pagination: {
        page: 1,
        pageSize: 50
      },
      decryptData: false
    };
    
    onSearch(searchRequest);
  };

  // 토큰에서 필터 생성
  const buildFiltersFromTokens = () => {
    const filters = [];
    let currentFilter = null;
    
    for (const token of tokens) {
      if (token.type === 'field') {
        currentFilter = { field: token.value, operator: null, value: null };
      } else if (token.type === 'operator' && currentFilter) {
        currentFilter.operator = token.value;
      } else if (token.type === 'value' && currentFilter) {
        currentFilter.value = token.value;
        filters.push(currentFilter);
        currentFilter = null;
      }
    }
    
    // 미완성 필터 처리
    if (currentFilter && currentFilter.field) {
      // 기본 연산자로 처리
      if (!currentFilter.operator) {
        currentFilter.operator = ':';
      }
      if (!currentFilter.value && inputValue.trim()) {
        currentFilter.value = inputValue.trim();
      }
      if (currentFilter.value) {
        filters.push(currentFilter);
      }
    }
    
    return filters;
  };

  // 토큰 타입별 스타일
  const getTokenClassName = (token) => {
    let className = 'search-token';
    if (token.status === 'invalid') {
      className += ' invalid';
    }
    return className;
  };

  return (
    <div className="advanced-search-form">
      <div className="search-input-container">
        <div className="token-list">
          {tokens.map(token => (
            <span
              key={token.id}
              className={getTokenClassName(token)}
              onClick={() => handleTokenEdit(token.id)}
              title="클릭하여 편집"
            >
              {token.type === 'field' && `${token.label || token.value}:`}
              {token.type === 'operator' && token.label}
              {token.type === 'value' && token.label || token.value}
              <button
                className="token-delete"
                onClick={(e) => {
                  e.stopPropagation();
                  handleTokenDelete(token.id);
                }}
              >
                ×
              </button>
            </span>
          ))}
        </div>
        <input
          ref={inputRef}
          type="text"
          className="search-input"
          placeholder="필드명을 입력하세요 (예: status, application)"
          value={inputValue}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          onFocus={() => {
            if (inputValue.trim() && suggestions.length > 0) {
              setShowSuggestions(true);
            }
          }}
          onBlur={() => {
            // 추천 클릭을 위해 약간의 지연
            setTimeout(() => setShowSuggestions(false), 200);
          }}
        />
        {showSuggestions && suggestions.length > 0 && (
          <div className="suggestion-dropdown" ref={suggestionRef}>
            {suggestions.map((suggestion, index) => (
              <div
                key={index}
                className={`suggestion-item ${index === suggestionIndex ? 'selected' : ''}`}
                onClick={() => handleSuggestionSelect(suggestion)}
                onMouseEnter={() => setSuggestionIndex(index)}
              >
                <span className="suggestion-label">{suggestion.label}</span>
                {suggestion.description && (
                  <span className="suggestion-description">{suggestion.description}</span>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
      <div className="search-actions">
        <button className="search-btn" onClick={handleSearch}>
          검색
        </button>
        <button 
          className="clear-btn" 
          onClick={() => {
            setTokens([]);
            setInputValue('');
            setShowSuggestions(false);
          }}
        >
          초기화
        </button>
      </div>
    </div>
  );
};

export default AdvancedSearchForm;

